CREATE TABLE carriers (
    carrier_cd CHAR(2) PRIMARY KEY,
    carrier_name VARCHAR(60) NOT NULL
);
CREATE TABLE airports (
    airport_cd CHAR(3) PRIMARY KEY,
    airport_name VARCHAR(100) NOT NULL,
    city VARCHAR(60),
    country VARCHAR(60)
);
CREATE TABLE aircraft (
    aircraft_id INT PRIMARY KEY,
    model VARCHAR(60) NOT NULL,
    capacity INT,
    carrier_cd CHAR(2) NOT NULL,
    FOREIGN KEY (carrier_cd) REFERENCES carriers(carrier_cd)
);
CREATE TABLE flights (
    flight_id INT PRIMARY KEY,
    flight_num VARCHAR(10) NOT NULL,
    carrier_cd CHAR(2) NOT NULL,
    origin_cd CHAR(3) NOT NULL,
    dest_cd CHAR(3) NOT NULL,
    aircraft_id INT NOT NULL,
    sched_dep_dt DATETIME,
    sched_arr_dt DATETIME,
    delay_min INT,
    status_cd CHAR(2),
    FOREIGN KEY (carrier_cd) REFERENCES carriers(carrier_cd),
    FOREIGN KEY (origin_cd) REFERENCES airports(airport_cd),
    FOREIGN KEY (dest_cd) REFERENCES airports(airport_cd),
    FOREIGN KEY (aircraft_id) REFERENCES aircraft(aircraft_id)
);
CREATE TABLE passengers (
    pax_id INT PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    email VARCHAR(120),
    loyalty_tier CHAR(3)
);
CREATE TABLE bookings (
    booking_id INT PRIMARY KEY,
    pax_id INT NOT NULL,
    flight_id INT NOT NULL,
    booking_dt DATE,
    fare_class CHAR(1),
    fare_amt DECIMAL(7,2),
    status_cd CHAR(2),
    FOREIGN KEY (pax_id) REFERENCES passengers(pax_id),
    FOREIGN KEY (flight_id) REFERENCES flights(flight_id)
);
